<?php require_once "../db.php";require_role("Teacher");$uid=current_id();$st=$conn->prepare("SELECT h.*,q.title,s.name student_name FROM quiz_history h JOIN quiz q ON q.id=h.quiz_id JOIN student s ON s.id=h.student_id WHERE q.created_by=? ORDER BY h.id DESC");$st->bind_param("i",$uid);$st->execute();$r=$st->get_result();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/teacher_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2 class="fw-bold">Student Results</h2><div class="card panel-card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Student</th><th>Quiz</th><th>Score</th><th>%</th><th>Date</th></tr></thead><tbody><?php while($d=$r->fetch_assoc()):$p=$d["total_questions"]?round($d["score"]/$d["total_questions"]*100,1):0;?><tr><td><?=e($d["student_name"])?></td><td><?=e($d["title"])?></td><td><?=$d["score"]?>/<?=$d["total_questions"]?></td><td><?=$p?>%</td><td><?=$d["created_at"]?></td></tr><?php endwhile;?></tbody></table></div></div></div></main></div></div></body></html>
